#!/usr/bin/env python3
from __future__ import annotations

import base64
import io
import subprocess
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ARCHIVE_SHA256 = "1041fea08595109f2698dab52619931f2afc3e382be3303577a47fee4a871f46"
ARCHIVE = """"""


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    if text.count(old) != 1:
        raise RuntimeError(f"expected one match in {path}: {old!r}, found {text.count(old)}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


raw = base64.b64decode(ARCHIVE)
import hashlib
if hashlib.sha256(raw).hexdigest() != ARCHIVE_SHA256:
    raise RuntimeError("provider archive digest mismatch")
with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as bundle:
    names = bundle.getnames()
    if any(name.startswith("/") or ".." in Path(name).parts for name in names):
        raise RuntimeError("unsafe provider archive path")
    bundle.extractall(ROOT)

build = ROOT / "api-center" / "build_catalog_market_search.py"
replace_once(
    build,
    'HEXDB_AVIATION_CATALOG = HERE / "hexdb-aviation/provider-catalog.json"\nKNOWLEDGE_TOOLS_CATALOG',
    'HEXDB_AVIATION_CATALOG = HERE / "hexdb-aviation/provider-catalog.json"\nWTO_CATALOG = HERE / "wto/provider-catalog.json"\nIMF_CATALOG = HERE / "imf/provider-catalog.json"\nFAOSTAT_CATALOG = HERE / "faostat/provider-catalog.json"\nKNOWLEDGE_TOOLS_CATALOG',
)
replace_once(
    build,
    '    "hexdb-aviation": 6,\n    "wolfram-alpha": 4,',
    '    "hexdb-aviation": 6,\n    "wto": 7,\n    "imf": 6,\n    "faostat": 7,\n    "wolfram-alpha": 4,',
)
replace_once(
    build,
    '    HEXDB_AVIATION_CATALOG,\n    KNOWLEDGE_TOOLS_CATALOG,',
    '    HEXDB_AVIATION_CATALOG,\n    WTO_CATALOG,\n    IMF_CATALOG,\n    FAOSTAT_CATALOG,\n    KNOWLEDGE_TOOLS_CATALOG,',
)
replace_once(
    build,
    '        "hexdb-aviation/provider-catalog.json",\n        "knowledge-tools/provider-catalog.json",',
    '        "hexdb-aviation/provider-catalog.json",\n        "wto/provider-catalog.json",\n        "imf/provider-catalog.json",\n        "faostat/provider-catalog.json",\n        "knowledge-tools/provider-catalog.json",',
)

test_catalog = ROOT / "api-center" / "tests" / "test_api_catalog.py"
replace_once(
    test_catalog,
    '    "hexdb-aviation": 6,\n    "wolfram-alpha": 4,',
    '    "hexdb-aviation": 6,\n    "wto": 7,\n    "imf": 6,\n    "faostat": 7,\n    "wolfram-alpha": 4,',
)
replace_once(test_catalog, 'catalog["managed_provider_count"], 42', 'catalog["managed_provider_count"], 45')
replace_once(test_catalog, 'catalog["enabled_managed_provider_count"], 42', 'catalog["enabled_managed_provider_count"], 45')
replace_once(test_catalog, 'catalog["managed_operation_count"], 451', 'catalog["managed_operation_count"], 471')
replace_once(
    test_catalog,
    '            "opensky-network": "OPEN_SKY_CLIENT_SECRET",\n            "wolfram-alpha":',
    '            "opensky-network": "OPEN_SKY_CLIENT_SECRET",\n            "wto": "WTO_API_KEY",\n            "faostat": "FAOSTAT_PASSWORD",\n            "wolfram-alpha":',
)

test_cap = ROOT / "api-center" / "tests" / "test_capability_maximization.py"
replace_once(test_cap, '            451,', '            471,')
replace_once(
    test_cap,
    '            "hexdb-aviation": 6,\n            "wolfram-alpha": 4,',
    '            "hexdb-aviation": 6,\n            "wto": 7,\n            "imf": 6,\n            "faostat": 7,\n            "wolfram-alpha": 4,',
)

subprocess.run(["python", str(ROOT / "api-center" / "build_catalog_market_search.py")], check=True)
print({"status": "PASS", "providers_added": 3, "operations_added": 20})
